function fewestStepsForKeys(grid: string[]): number {
  const R = grid.length, C = grid[0].length;
  const pos: number[][] = []; // pos[0] = start, pos[1 + j] = key j
  let k = 0;
  for (let y = 0; y < R; y++) for (let x = 0; x < C; x++) {
    const ch = grid[y][x];
    if (ch === "@") pos[0] = [y, x];
    else if (ch >= "a" && ch <= "f") { pos[1 + ch.charCodeAt(0) - 97] = [y, x]; k++; }
  }
  const goal = (1 << k) - 1;
  // steps from a stop to each key not in mask, never walking through a key not yet held
  const reach = (sy: number, sx: number, mask: number): Map<number, number> => {
    const dist = grid.map(row => new Array(row.length).fill(-1));
    dist[sy][sx] = 0;
    const q = [[sy, sx]], found = new Map<number, number>();
    for (let h = 0; h < q.length; h++) {
      const [y, x] = q[h];
      for (const [dy, dx] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const ny = y + dy, nx = x + dx;
        if (ny < 0 || ny >= R || nx < 0 || nx >= C || dist[ny][nx] >= 0) continue;
        const ch = grid[ny][nx];
        if (ch === "#") continue;
        if (ch >= "A" && ch <= "F" && !(mask & (1 << (ch.charCodeAt(0) - 65)))) continue;
        dist[ny][nx] = dist[y][x] + 1;
        if (ch >= "a" && ch <= "f" && !(mask & (1 << (ch.charCodeAt(0) - 97)))) { found.set(ch.charCodeAt(0) - 97, dist[ny][nx]); continue; }
        q.push([ny, nx]);
      }
    }
    return found;
  };
  const best = new Map<number, number>(); // key: stop * 64 + mask
  const pq: number[][] = [[0, 0, 0]];     // [steps, stop, mask], small enough for a sorted array
  best.set(0, 0);
  while (pq.length) {
    pq.sort((a, b) => b[0] - a[0]);
    const [d, stop, mask] = pq.pop()!;
    if (mask === goal) return d;
    if (best.get(stop * 64 + mask)! < d) continue;
    const [y, x] = pos[stop];
    for (const [key, steps] of reach(y, x, mask)) {
      const nm = mask | (1 << key), id = (key + 1) * 64 + nm, nd = d + steps;
      if (!best.has(id) || best.get(id)! > nd) { best.set(id, nd); pq.push([nd, key + 1, nm]); }
    }
  }
  return -1;
}

