class Solution:
    def fewestStepsForKeys(self, grid: List[str]) -> int:
        R, C = len(grid), len(grid[0])
        pos, k = {}, 0
        for y in range(R):
            for x in range(C):
                ch = grid[y][x]
                if ch == "@":
                    pos[0] = (y, x)
                elif "a" <= ch <= "f":
                    pos[1 + ord(ch) - 97] = (y, x)
                    k += 1
        goal = (1 << k) - 1

        def reach(sy, sx, mask):
            dist = {(sy, sx): 0}
            q, found = deque([(sy, sx)]), {}
            while q:
                y, x = q.popleft()
                for ny, nx in ((y + 1, x), (y - 1, x), (y, x + 1), (y, x - 1)):
                    if not (0 <= ny < R and 0 <= nx < C) or (ny, nx) in dist:
                        continue
                    ch = grid[ny][nx]
                    if ch == "#" or ("A" <= ch <= "F" and not mask >> (ord(ch) - 65) & 1):
                        continue
                    dist[(ny, nx)] = dist[(y, x)] + 1
                    if "a" <= ch <= "f" and not mask >> (ord(ch) - 97) & 1:
                        found[ord(ch) - 97] = dist[(ny, nx)]  # stop here: this key gets picked up
                        continue
                    q.append((ny, nx))
            return found

        best = {(0, 0): 0}
        pq = [(0, 0, 0)]
        while pq:
            d, stop, mask = heapq.heappop(pq)
            if mask == goal:
                return d
            if best[(stop, mask)] < d:
                continue
            y, x = pos[stop]
            for key, steps in reach(y, x, mask).items():
                state, nd = (key + 1, mask | 1 << key), d + steps
                if nd < best.get(state, float("inf")):
                    best[state] = nd
                    heapq.heappush(pq, (nd, *state))
        return -1

