function fewestStepsForKeys(grid: string[]): number {
  const R = grid.length, C = grid[0].length;
  let sy = 0, sx = 0, k = 0;
  for (let y = 0; y < R; y++) for (let x = 0; x < C; x++) {
    const ch = grid[y][x];
    if (ch === "@") { sy = y; sx = x; }
    else if (ch >= "a" && ch <= "f") k++;
  }
  const goal = (1 << k) - 1;
  if (goal === 0) return 0;
  const seen = new Uint8Array(R * C * 64);
  seen[(sy * C + sx) * 64] = 1;
  let frontier = [[sy, sx, 0]];
  for (let steps = 1; frontier.length; steps++) {
    const next: number[][] = [];
    for (const [y, x, mask] of frontier) {
      for (const [dy, dx] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const ny = y + dy, nx = x + dx;
        if (ny < 0 || ny >= R || nx < 0 || nx >= C) continue;
        const ch = grid[ny][nx];
        if (ch === "#") continue;
        if (ch >= "A" && ch <= "F" && !(mask & (1 << (ch.charCodeAt(0) - 65)))) continue;
        const nm = ch >= "a" && ch <= "f" ? mask | (1 << (ch.charCodeAt(0) - 97)) : mask;
        if (nm === goal) return steps;
        const id = (ny * C + nx) * 64 + nm;
        if (seen[id]) continue;
        seen[id] = 1;
        next.push([ny, nx, nm]);
      }
    }
    frontier = next;
  }
  return -1;
}

